describe('Mobile Responsive Sauce Demo Store', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display inventory page on mobile portrait viewport with burger menu visible', () => {
    cy.viewport('375x812');
    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="page-wrapper"]').should('contain', 'Inventory');
    cy.get('[data-testid="react-burger-menu-btn"]').should('be.visible');
    cy.get('[data-testid="open-menu"]').click();
    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');
    cy.get('[data-testid="close-menu"]').click();
    cy.get('[data-testid="react-burger-cross-btn"]').should('be.visible');
  });

  it('should handle burger menu button click and close on mobile portrait viewport', () => {
    cy.viewport('375x812');
    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="page-wrapper"]').should('contain', 'Inventory');
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-testid="close-menu"]').click();
    cy.get('[data-testid="react-burger-menu-btn"]').should('not.exist');
    cy.get('[data-testid="page-wrapper"]').should('contain', 'Inventory');
  });
});
